function SectionHeading({ eyebrow, children }) { return <div className="section-head"><div className="eyebrow">{eyebrow}</div><h2>{children}</h2><div className="gold-rule" /></div> }
function AnimatedHeroHeading() {
  const headingRef = useRef(null)
  useEffect(() => {
    const split = splitText(headingRef.current, { lines: true, words: true })
    let lineAnimation
    let removeHoverEffects = () => {}
    split.addEffect(({ lines, words }) => {
      lineAnimation = animate(lines, { y: ['50%', '-50%'], loop: true, alternate: true, delay: stagger(400), ease: 'inOutQuad' })
      const handlers = words.map((word) => {
        const handler = () => animate(word, { color: utils.randomPick(['#FF4B4B', '#FFCC2A', '#B7FF54', '#57F695']), duration: 250 })
        word.addEventListener('pointerenter', handler)
        return [word, handler]
      })
      removeHoverEffects = () => handlers.forEach(([word, handler]) => word.removeEventListener('pointerenter', handler))
      return removeHoverEffects
    })
    return () => { lineAnimation?.pause(); removeHoverEffects(); split.revert?.() }
  }, [])
  return <h1 ref={headingRef}>Building Financial Legacies with<br className="desktop-only" /> Integrity</h1>
}
function GrowButton({ children, href, variant = 'primary' }) {
  const buttonRef = useRef(null)
  const animateScale = (scale) => animate(buttonRef.current, { scale, duration: 280, ease: 'outBack' })
  return <a ref={buttonRef} className={`btn btn-${variant} hero-grow-button`} href={href} onPointerEnter={() => animateScale(1.07)} onPointerLeave={() => animateScale(1)}>{children}</a>
}
function Home() { const homeServices = [['◈', 'Audit & Assurance', 'Rigorous, independent financial verification ensuring absolute compliance and fostering stakeholder confidence in an evolving regulatory landscape.'], ['▤', 'Tax Advisory', 'Strategic tax planning and compliance tailored to Tanzanian legislation, optimizing structures for growth.'], ['↗', 'Financial Consulting', 'Deep analytical insights and valuation services to guide mergers, acquisitions, and strategic restructuring.'], ['◇', 'Risk Management', 'Proactive identification and mitigation of enterprise risks, establishing robust internal controls to safeguard your financial legacy against market volatility.']]; return <><section className="reference-hero"><div className="reference-hero-content"><AnimatedHeroHeading /><p>Trusted advisors for Tanzanian businesses navigating company registration, tax compliance, payroll, licensing, and growth. We help founders, family enterprises, and corporates move from complexity to confidence.</p><div className="hero-actions"><GrowButton href="#proposal">Consult with Experts</GrowButton><GrowButton href="#services" variant="outline">Explore Services</GrowButton></div></div></section><section className="section"><div className="container"><div className="split"><div><div className="eyebrow">Operating in Tanzania</div><h3>Registration, licensing, and statutory compliance that keep businesses moving.</h3><p>From company formation and annual returns to tax filings, payroll obligations, and sector approvals, we support businesses across the full compliance lifecycle. Our advice blends technical excellence with practical understanding of Tanzania's regulatory environment.</p></div><div className="panel"><div className="eyebrow">Key regulators &amp; bodies</div><ul style={{ margin: '14px 0 0', paddingLeft: 18, lineHeight: 1.8, color: 'var(--muted)' }}><li>BRELA for company incorporation, annual returns, and entity compliance.</li><li>TRA for VAT, income tax, withholding tax, and filing discipline.</li><li>COSOTA and transport-sector regulators for operational and commercial compliance.</li><li>TCAA and other licensing authorities for aviation and sector specific approvals.</li><li>NSSF, NHIF, WCF, and labour/payroll obligations for workforce compliance.</li><li>Sector regulators and local licensing bodies for business growth and expansion.</li></ul></div></div></div></section><section className="reference-expertise"><div className="container"><SectionHeading>Core Expertise</SectionHeading><div className="reference-bento">{homeServices.map(([icon, title, text], index) => <article className={`reference-card ${index === 0 || index === 3 ? 'reference-wide' : ''}`} key={title}><div><div className={`reference-icon ${index % 2 ? 'cyan' : ''}`}>{icon}</div><h3>{title}</h3><p>{text}</p></div>{<a href={homeServiceRoutes[index]}>Learn more →</a>}</article>)}</div></div></section><section className="trusted-band"><div className="container"><SectionHeading>Trusted by Industry Leaders</SectionHeading><div className="client-logos">{['LOGO 1', 'LOGO 2', 'LOGO 3', 'LOGO 4', 'LOGO 5', 'LOGO 6'].map((logo) => <span key={logo}>{logo}</span>)}</div><a className="btn btn-outline" href="#contact">Join our Client List</a></div></section></> }
